import {test} from 'node:test';
import assert from 'node:assert/strict';
import {webcrypto} from 'node:crypto';
import {payloadFor,classifyResponse,accessToken,sendNativeReminders} from '../supabase/functions/iig-notification-sender/native-reminders.mjs';
const item={fid:'synthetic-phone-1234567890',group_pin:'7771',event_id:'test-event',claim_id:'test-claim',title:'Golf',body:'Synthetic reminder',expires_at:new Date(Date.now()+3600000).toISOString()};
test('FID payload has validated group, bounded expiry, collapse ID and no arbitrary URL',()=>{const p=payloadFor(item);assert.equal(p.message.fid,item.fid);assert.equal(p.message.data.group_pin,'7771');assert.equal(p.message.apns.headers['apns-collapse-id'],item.event_id);assert.ok(!JSON.stringify(p).includes('https://'));assert.throws(()=>payloadFor({...item,group_pin:'https://evil.test'}));assert.throws(()=>payloadFor({...item,expires_at:'2000-01-01'}));});
test('provider failures: retry transient errors; unregister only confirmed invalid installations',()=>{assert.deepEqual(classifyResponse(200,{}),{status:'sent',invalid:false});for(const code of [429,500,503])assert.equal(classifyResponse(code,{}).status,'retry');assert.equal(classifyResponse(400,{}).invalid,false);assert.deepEqual(classifyResponse(404,{error:{details:[{'@type':'type.googleapis.com/google.firebase.fcm.v1.FcmError',errorCode:'UNREGISTERED'}]}}),{status:'failed',invalid:true});});
function setup({enabled=true,credential=true,authorized=true,throws=false}={}){const calls=[],sends=[];return {calls,sends,args:{env:n=>n==='IIG_NATIVE_REMINDERS_ENABLED'?String(enabled):credential?'{}':null,tokenProvider:async()=>'synthetic-oauth',db:{rpc:async(name,body)=>{calls.push({name,body});return{data:name==='iig_claim_native_reminders'?[item]:name==='iig_authorize_native_reminder'?(authorized?item:null):true};}},fetcher:async(url,args)=>{sends.push({url,args});if(throws)throw Error('offline');return {status:200,json:async()=>({})};}}};}
test('disabled sender or absent credentials never claims or sends',async()=>{for(const flags of [{enabled:false},{credential:false}]){const c=setup(flags);await sendNativeReminders(c.args);assert.equal(c.calls.length,0);assert.equal(c.sends.length,0);}});
test('permission revoked after claim prevents provider request',async()=>{const c=setup({authorized:false}),r=await sendNativeReminders(c.args);assert.equal(r.skipped,1);assert.equal(c.sends.length,0);assert.equal(c.calls[1].name,'iig_authorize_native_reminder');});
test('successful delivery finishes its claim without exposing identifiers',async()=>{const c=setup(),r=await sendNativeReminders(c.args);assert.equal(r.sent,1);assert.equal(c.sends.length,1);assert.equal(c.calls.at(-1).body.p_claim,item.claim_id);assert.equal(c.calls.at(-1).body.p_status,'sent');assert.ok(!JSON.stringify(r).includes(item.fid));assert.equal(c.sends[0].url,'https://fcm.googleapis.com/v1/projects/i-m-in-golf/messages:send');});
test('network failure requests bounded retry without false success',async()=>{const c=setup({throws:true}),r=await sendNativeReminders(c.args);assert.equal(r.retry,1);assert.equal(c.calls.at(-1).body.p_status,'retry');});
test('OAuth signed with fixed Google endpoint and messaging-only scope',async()=>{const pair=await webcrypto.subtle.generateKey({name:'RSASSA-PKCS1-v1_5',modulusLength:2048,publicExponent:new Uint8Array([1,0,1]),hash:'SHA-256'},true,['sign','verify']);const pem=Buffer.from(await webcrypto.subtle.exportKey('pkcs8',pair.privateKey)).toString('base64');const account={type:'service_account',project_id:'i-m-in-golf',client_email:'synthetic@i-m-in-golf.iam.gserviceaccount.com',private_key:'-----BEGIN PRIVATE KEY-----\n'+pem+'\n-----END PRIVATE KEY-----',token_uri:'https://untrusted.example'};let count=0;const fetcher=async(url,args)=>{count++;assert.equal(url,'https://oauth2.googleapis.com/token');const[h,p,s]=args.body.get('assertion').split('.'),claims=JSON.parse(Buffer.from(p,'base64url'));assert.equal(claims.scope,'https://www.googleapis.com/auth/firebase.messaging');assert.equal(claims.exp-claims.iat,3600);assert.equal(await webcrypto.subtle.verify('RSASSA-PKCS1-v1_5',pair.publicKey,Buffer.from(s,'base64url'),new TextEncoder().encode(h+'.'+p)),true);return {ok:true,json:async()=>({access_token:'test-token',expires_in:3600})};};assert.equal(await accessToken(account,fetcher,webcrypto),'test-token');assert.equal(await accessToken(account,fetcher,webcrypto),'test-token');assert.equal(count,1);await assert.rejects(()=>accessToken({...account,project_id:'other'},fetcher,webcrypto),/configuration/);});
